changeSet.sql:
alter table exercise_attempt add column exercise_snapshot_json json null;
update exercise_attempt a join exercise e on e.id = a.exercise_id set a.exercise_snapshot_json = json_object( 'domainId', e.domain_id, 'stages', e.stages_json, 'tags', if(trim(e.tags) = '', json_array(), cast(concat('["', regexp_replace(trim(e.tags), '[[:space:]]*,[[:space:]]*', '","'), '"]') as json)), 'answerReaction', json_extract(e.options_json, '$.answerReaction'));
alter table exercise_attempt modify column exercise_snapshot_json json not null;
